from dashboard_ui import build_dashboard_context
from research_dashboard import load_research_status, unavailable_research_status
import os
import json
from datetime import datetime, timezone
from flask import Flask, render_template_string
from dotenv import load_dotenv
from apscheduler.schedulers.background import BackgroundScheduler
import ingestion
from weekly_stats import shadow_roi, weekly_pick_summary

load_dotenv()
app = Flask(__name__)

# Initialize Database safely
try:
    from db import SessionLocal, PickLog, ParlaySlip, engine, Base, init_db
    init_db()
    DB_AVAILABLE = True
except Exception as e:
    print(f"Database initialization warning: {e}")
    DB_AVAILABLE = False

# Safe Background Scheduler Initialization
if os.getenv("INGESTION_SCHEDULER_ENABLED", "true").strip().lower() in ("1", "true", "yes", "on"):
    try:
        scheduler = BackgroundScheduler()
        scheduler.add_job(
            func=ingestion.fetch_and_store_live_data, trigger="interval", minutes=60,
            next_run_time=datetime.now(timezone.utc), max_instances=1, coalesce=True,
        )
        scheduler.start()
        print("Background ingestion scheduler started.")
    except Exception as e:
        print(f"Failed to start scheduler: {e}")
else:
    print("Background ingestion scheduler disabled for this process.")

HTML_TEMPLATE = '\n<!DOCTYPE html>\n<html>\n<head>\n    <title>Ogbreeze Command Center</title>\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n    <meta http-equiv="refresh" content="60">\n    <style>\n        body {\n            margin: 0; padding: 20px;\n            background: #0d1117; color: #c9d1d9;\n            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;\n        }\n        main { max-width: 1250px; margin: auto; }\n        h1 { color: #58a6ff; font-size: 24px; margin-bottom: 6px; }\n        h2 { font-size: 18px; color: #58a6ff; margin-top: 28px; }\n        .muted { color: #8b949e; font-size: 12px; line-height: 1.6; }\n        .metrics, .cards {\n            display: grid; gap: 12px;\n            grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));\n        }\n        .metric, .card, details {\n            background: #161b22; border: 1px solid #30363d;\n            border-radius: 8px; padding: 15px;\n        }\n        .metric span { display: block; font-size: 23px; margin-top: 8px; color: #f0f6fc; }\n        .metric small { display: block; margin-top: 5px; color: #8b949e; }\n        .card-header { display: flex; justify-content: space-between; gap: 10px; }\n        .price, .won { color: #3fb950; }\n        .lost { color: #f85149; }\n        .review { color: #d29922; }\n        ul { padding-left: 20px; font-size: 13px; line-height: 1.8; }\n        .table-wrap { overflow-x: auto; }\n        table { width: 100%; border-collapse: collapse; font-size: 13px; }\n        th, td { padding: 11px; border-bottom: 1px solid #30363d; text-align: left; }\n        th { color: #8b949e; }\n        summary { cursor: pointer; color: #58a6ff; }\n        details { margin-top: 16px; }\n        .empty { color: #8b949e; padding: 12px 0; }\n        .error { border: 1px solid #f85149; padding: 15px; }\n        .research-status { background: #211b0c; border: 1px solid #d29922;\n            border-radius: 8px; padding: 16px; margin: 20px 0; }\n        .research-status h2 { color: #d29922; margin-top: 0; }\n    </style>\n</head>\n<body>\n<main>\n    <h1>⚡ OGBREEZE COMMAND CENTER</h1>\n    <p class="muted">{{ week_label }} · Chicago time · {{ timestamp }}</p>\n\n    <section class="research-status" aria-label="Research and generation status">\n        <h2>Automatic parlays: {{ research.generation_status }}</h2>\n        <p>No research-qualified selector is enabled. Existing tickets are preserved,\n           not newly approved recommendations.</p>\n        <p class="muted">Production model: {{ research.model_approval }}.\n           Experimental training status: {{ research.experimental_training_status }}.</p>\n        <div class="metrics">\n            <div class="metric">Frozen observations · all time\n                <span>{{ research.observation_count if research.observation_count is not none else \'—\' }}</span>\n            </div>\n            <div class="metric">Distinct captured games · all time\n                <span>{{ research.distinct_events if research.distinct_events is not none else \'—\' }}</span>\n            </div>\n            <div class="metric">Eligible settled games · default policy\n                <span>{{ research.eligible_settled_events if research.eligible_settled_events is not none else \'—\' }}</span>\n                <small>Capture 1–24h before kickoff; provider quote age at most 60min</small>\n            </div>\n        </div>\n        {% if not research.available %}\n        <p class="review">Research counts unavailable. Check logs; unknown is not zero.</p>\n        {% else %}\n        <p class="muted">Recent gate audit events (last 2h): {{ research.recent_audit_events }}.\n            Last audit: {{ research.last_audit_utc or \'None in the last 2h\' }}.</p>\n        <ul>\n            {% for blocker in research.blockers %}\n            <li>{{ blocker.label }} — {{ blocker.count }} audited event(s)</li>\n            {% else %}\n            <li>No recent stored blocker details. Automatic creation remains paused.</li>\n            {% endfor %}\n        </ul>\n        {% if research.invalid_audit_rows %}\n        <p class="review">{{ research.invalid_audit_rows }} invalid audit row(s) omitted.</p>\n        {% endif %}\n        {% endif %}\n        <p class="muted">These counts describe stored evidence, not a prediction of winning.\n            Weather and venue research remain excluded.</p>\n    </section>\n\n\n    {% if not available %}\n    <p class="error">Dashboard data unavailable. Check deployment logs.</p>\n    {% else %}\n\n    <div class="metrics">\n        <div class="metric">This Week’s Straight Picks\n            <span>{{ straight_count }}</span>\n            <small>Shadow tracking records—not research-qualified recommendations</small>\n        </div>\n        <div class="metric">Pending Selections\n            <span>{{ pending_selections }}</span>\n            <small>This week’s unique tracked selections</small>\n        </div>\n        <div class="metric">Pending Tickets\n            <span>—</span>\n            <small>Awaiting ticket-to-leg outcome links</small>\n        </div>\n        <div class="metric">Weekly Selection Record\n            <span>{{ record }}</span>\n            <small>Wins–losses–pushes · Win rate {{ win_rate }}</small>\n        </div>\n    </div>\n\n    {% if review_count %}\n    <p class="muted review">{{ review_count }} current-week selection(s) require review.</p>\n    {% endif %}\n\n    <h2>🎯 Preserved Parlay Tickets</h2>\n    <p class="muted">\n        Preserved legacy slips—not newly research-qualified recommendations. Returns are estimates,\n        not confirmed sportsbook wagers or accepted quotes.\n    </p>\n    <div class="cards">\n        {% for ticket in active_tickets %}\n        <div class="card">\n            <div class="card-header">\n                <span>{{ ticket.category }}</span>\n                <span class="price">{{ ticket.odds }}</span>\n            </div>\n            <div class="muted review">{{ ticket.research_label }}</div>\n            <ul>{% for leg in ticket.legs %}<li>{{ leg }}</li>{% endfor %}</ul>\n            <div class="muted">\n                Stake {{ ticket.stake }} · Potential return {{ ticket.payout }}<br>\n                Ticket #{{ ticket.id }} · Outcome {{ ticket.outcome }}\n            </div>\n        </div>\n        {% else %}\n        <p class="empty">No preserved parlay slips.</p>\n        {% endfor %}\n    </div>\n\n    <details>\n        <summary>📥 Micro Sandbox · {{ micro_tickets | length }} preserved slips</summary>\n        <div class="table-wrap">\n        <table>\n            <tr><th>Selections</th><th>Stake</th><th>Odds</th><th>Potential Return</th></tr>\n            {% for ticket in micro_tickets %}\n            <tr>\n                <td>{{ ticket.legs | join(\' + \') }}<br><small class="review">{{ ticket.research_label }}</small></td>\n                <td>{{ ticket.stake }}</td>\n                <td>{{ ticket.odds }}</td>\n                <td>{{ ticket.payout }}</td>\n            </tr>\n            {% else %}\n            <tr><td colspan="4">No preserved Micro slips.</td></tr>\n            {% endfor %}\n        </table>\n        </div>\n    </details>\n\n    <h2>🏈 Straight Game Picks · Shadow Baseline</h2>\n    <p class="muted">\n        Shadow moneyline records for tracking and evaluation only.\n        These are not approved research-backed bets or instructions to place wagers.\n    </p>\n\n    {% macro straight_table(rows) %}\n    <div class="table-wrap">\n    <table>\n        <tr><th>Game</th><th>Pick</th><th>Odds</th><th>Kickoff</th><th>Result</th></tr>\n        {% for pick in rows %}\n        <tr>\n            <td>{{ pick.game }}</td><td>{{ pick.pick }}</td>\n            <td>{{ pick.odds }}</td><td>{{ pick.kickoff }}</td>\n            <td class="{{ \'won\' if pick.status == \'WON\' else (\'lost\' if pick.status == \'LOST\' else \'\') }}">\n                {{ pick.status }}\n            </td>\n        </tr>\n        {% else %}\n        <tr><td colspan="5">No dated standalone picks recorded for this week.</td></tr>\n        {% endfor %}\n    </table>\n    </div>\n    {% endmacro %}\n\n    {{ straight_table(straight_preview) }}\n    {% if straight_more %}\n    <details>\n        <summary>Show {{ straight_more | length }} more straight picks</summary>\n        {{ straight_table(straight_more) }}\n    </details>\n    {% endif %}\n\n    <details>\n        <summary>🗓 This Week’s Games · {{ games | length }} recorded games</summary>\n        <p class="muted">\n            Games represented in stored engine selections—not a complete schedule feed.\n            Listing a game here does not designate it as a pick.\n        </p>\n        <div class="table-wrap">\n        <table>\n            <tr><th>Game</th><th>Kickoff</th></tr>\n            {% for game in games %}\n            <tr><td>{{ game.game }}</td><td>{{ game.kickoff }}</td></tr>\n            {% else %}\n            <tr><td colspan="2">No dated games recorded for this week.</td></tr>\n            {% endfor %}\n        </table>\n        </div>\n    </details>\n\n    <details>\n        <summary>📊 Weekly Selection History</summary>\n        <div class="table-wrap">\n        <table>\n            <tr>\n                <th>Week</th><th>Wins</th><th>Losses</th><th>Pushes</th>\n                <th>Pending</th><th>Review</th><th>Win Rate</th>\n            </tr>\n            {% for week in weekly_summary.weeks %}\n            <tr>\n                <td>{{ week.label }}</td><td>{{ week.wins }}</td>\n                <td>{{ week.losses }}</td><td>{{ week.pushes }}</td>\n                <td>{{ week.pending }}</td><td>{{ week.review }}</td>\n                <td>{{ week.win_rate }}</td>\n            </tr>\n            {% endfor %}\n        </table>\n        </div>\n    </details>\n\n    <details>\n        <summary>🧾 Ticket History · latest {{ ticket_history | length }} preserved slips</summary>\n        <p class="muted">\n            Display status is separate from betting outcome.\n            ACTIVE and ARCHIVED do not mean pending, won, or lost.\n            Repeated engine-generated versions are not confirmed placed bets.\n            Ticket outcomes remain untracked until structured ticket links are added.\n        </p>\n        <div class="table-wrap">\n        <table>\n            <tr>\n                <th>Ticket</th><th>Created</th><th>Category</th>\n                <th>Display Status</th><th>Outcome</th><th>Qualification</th><th>Legs</th>\n            </tr>\n            {% for ticket in ticket_history %}\n            <tr>\n                <td>#{{ ticket.id }}</td><td>{{ ticket.created }}</td>\n                <td>{{ ticket.category }}</td><td>{{ ticket.display_status }}</td>\n                <td>{{ ticket.outcome }}</td>\n                <td>{{ ticket.research_label }}</td>\n                <td>\n                    <details>\n                        <summary>View</summary>\n                        <ul>{% for leg in ticket.legs %}<li>{{ leg }}</li>{% endfor %}</ul>\n                    </details>\n                </td>\n            </tr>\n            {% endfor %}\n        </table>\n        </div>\n    </details>\n\n    {% if undated %}\n    <p class="muted">\n        {{ undated }} stored selection(s) lack kickoff dates and are excluded from current-week totals.\n    </p>\n    {% endif %}\n\n    {% endif %}\n</main>\n</body>\n</html>\n'

@app.route("/")
def dashboard_view():
    data = build_dashboard_context([], [])
    data["research"] = unavailable_research_status()
    available = False

    if DB_AVAILABLE:
        try:
            with SessionLocal() as session:
                picks = session.query(PickLog).all()
                slips = session.query(ParlaySlip).all()
                data = build_dashboard_context(picks, slips)
                data["research"] = load_research_status(session)
                available = True
        except Exception as error:
            print(f"Dashboard query error: {error}")

    return render_template_string(
        HTML_TEMPLATE, available=available, **data
    )

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 8080))
    app.run(host="0.0.0.0", port=port)